        // Observe before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Trigger C's fallback by sending Ether directly to its address
        (bool ok, ) = address(c).call{value: sendAmount}("");
        require(ok, "send to c failed");

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Try owner-only functions and record whether they reverted
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(1) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(targetForSend, 0) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // General rule: fallback increments depositsCount by exactly 1 and increases balance by sendAmount,
        // and all owner-only actions revert when called from this (non-owner) contract.
        assert(
            afterDeposits == beforeDeposits + 1
            && afterBalance == beforeBalance + sendAmount
            && withdrewAllReverted == true
            && withdrawReverted == true
            && sendMoneyReverted == true
        );
    }

    // allow receiving ETH back if needed
    receive() external payable {}
}

