contract InvMutTest {
    C c;
    address other;
    constructor(C _c) { c = _c; other = address(0x1234); }

    // We will try to call withdraw/withdrawAll as the owner (this contract) and as a non-owner
    // Inputs: amount to send to fallback (to increase depositsCount and contract balance),
    //         withdrawAmount to attempt to withdraw, and a flag tryAsOther indicating whether
    //         to attempt a non-owner call (simulated by using address.call).
    function run(uint amount, uint withdrawAmount, bool tryAsOther) public payable {
        require(address(this).balance >= amount, "need funds to send");
        // initial observations
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Send Ether to c to trigger fallback which increments depositsCount
        // Must send as this contract (owner), so success expected
        c.f{value: amount}();

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // The fallback increments depositsCount by exactly 1 and balance increases by amount
        assert(afterCount == beforeCount + 1 && afterBal == beforeBal + amount);

        // Now attempt withdraw as owner: should succeed and reduce c balance by withdrawAmount (or transfer available)
        // Capture revert flag
        bool ownerReverted;
        uint balBeforeWithdraw = address(c).balance;
        try c.withdraw(withdrawAmount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }
        uint balAfterWithdraw = address(c).balance;

        // If owner call did not revert, c's balance must have decreased by at most withdrawAmount (transfer may fail only on revert),
        // but since owner call succeeded, balance should be balBeforeWithdraw - withdrawAmount
        if (!ownerReverted) {
            assert(balAfterWithdraw == balBeforeWithdraw - withdrawAmount);
        } else {
            // If owner revert, balance unchanged
            assert(balAfterWithdraw == balBeforeWithdraw);
        }

        // Optionally attempt a non-owner withdrawal by making a low-level call from this contract
        // We simulate non-owner by using call to c.withdraw with encoded selector but as msg.sender will still be this contract.
        // To actually simulate a non-owner, we perform a call to c via address.call using a different from-address is impossible here,
        // so instead we check that only this contract (owner) can call: try invoking withdraw via c.sendMoney to a contract that calls withdraw
        // We'll deploy a minimal attacker inline via create is not allowed. So instead use try/catch on sendMoney to a nonpayable target and regard this branch optional.

        // Final general assert: depositsCount increased by exactly 1 from earlier, and if a non-owner attempt was made it must revert and leave c state unchanged.
        // We cannot change msg.sender to another address in this environment, so enforce the invariant that depositsCount >= beforeCount + 1 and
        // that ownerWithdraw either reduced balance by withdrawAmount (when not reverted) or left it unchanged (when reverted).
        assert(c.depositsCount() >= beforeCount + 1 && (ownerReverted ? address(c).balance == balBeforeWithdraw : address(c).balance == balBeforeWithdraw - withdrawAmount));
    }

    // Allow this contract to receive Ether when c.withdraw sends funds back
    receive() external payable {}
}

