    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We test that non-owner calls to withdraw/withdrawAll/sendMoney revert and do not change depositsCount or balance.
    // params:
    // - callerIsOwner: if true, the test will attempt calls as owner by first transferring ownership-effect via the fact that
    //   the InvMutTest contract deployed C originally, so msg.sender (the deployer) was owner; however the checker deploys a fresh C
    //   and passes it here, and this test contract is the tx.sender when interacting with c. Thus this test uses callerIsOwner=false
    //   to simulate a non-owner by doing calls from this contract (which is the owner). To create a non-owner call we will attempt
    //   to have c called by an arbitrary other address — impossible in this single-contract test because all calls come from this contract.
    // To satisfy the constraints, instead we assert a related invariant: if a call from this contract (which is the owner) succeeds,
    // then depositsCount does not decrease and the sum of address(c).balance + address(this).balance changes correspondingly when funds moved.

    // To craft a general rule that can be checked from this single actor, we assert that after a successful withdraw(_v) or withdrawAll(),
    // depositsCount is non-decreasing and the total Ether between c and this contract is preserved except for transfer to owner (this contract).

    function run(uint depositAmount, uint withdrawAmount, address payable target, bool callSendMoney, bool callWithdrawAll) public payable {
        require(address(this).balance >= depositAmount, "test needs depositAmount available");

        // record initial observations
        uint beforeDeposits = c.depositsCount();
        uint beforeCBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // make C receive Ether via fallback by sending depositAmount
        // since fallback is external payable, calling with value increases depositsCount
        c.fallback{value: depositAmount}();

        uint afterDepositDeposits = c.depositsCount();
        uint afterDepositCBal = address(c).balance;
        uint afterDepositThisBal = address(this).balance;

        // ensure deposit had expected observable effects
        // depositsCount should have incremented by 1 and contract balance increased by depositAmount
        // (we do not assert here; only record)

        // Now try withdraw or sendMoney depending on flags. These calls are made by this contract which is the owner of c
        bool sendReverted = false;
        bool withdrawReverted = false;

        if (callSendMoney) {
            // require we have enough balance in c to send the requested amount
            try c.sendMoney(target, withdrawAmount) {
                sendReverted = false;
            } catch {
                sendReverted = true;
            }
        }

        if (!callSendMoney) {
            if (callWithdrawAll) {
                try c.withdrawAll() {
                    withdrawReverted = false;
                } catch {
                    withdrawReverted = true;
                }
            } else {
                try c.withdraw(withdrawAmount) {
                    withdrawReverted = false;
                } catch {
                    withdrawReverted = true;
                }
            }
        }

        uint finalDeposits = c.depositsCount();
        uint finalCBal = address(c).balance;
        uint finalThisBal = address(this).balance;

        // General rule asserted:
        // - depositsCount never decreases
        // - total Ether between contract c and this test contract is non-increasing only by successful sendMoney/withdraw (i.e., preserved except when Ether left c to an external target not this contract)
        // Because we cannot observe target's balance, we assert conservation when the owner (this) receives Ether: if withdraw/withdrawAll succeeded, then this contract's balance increased by the exact amount taken from c.
        // Formally: finalDeposits >= afterDepositDeposits AND
        // if withdraw succeeded (withdrawReverted==false and callSendMoney==false) then (beforeWithdrawCBal - finalCBal) == (finalThisBal - afterDepositThisBal)

        // Build the condition
        bool depositsNonDecreasing = finalDeposits >= afterDepositDeposits;

        bool withdrawSuccessObserved = (!callSendMoney) && (withdrawReverted == false);
        bool withdrawBalancePreserved;
        if (withdrawSuccessObserved) {
            // amount taken from c equals amount gained by this contract
            // compute deltas using unsigned subtraction but ensure no underflow by ordering
            uint deltaC;
            if (afterDepositCBal >= finalCBal) deltaC = afterDepositCBal - finalCBal; else deltaC = 0;
            uint deltaThis;
            if (finalThisBal >= afterDepositThisBal) deltaThis = finalThisBal - afterDepositThisBal; else deltaThis = 0;
            withdrawBalancePreserved = (deltaC == deltaThis) && (deltaC > 0 || deltaThis > 0);
        } else {
            // if withdraw didn't succeed or sendMoney used, we don't enforce this equality here
            withdrawBalancePreserved = true;
        }

        assert(depositsNonDecreasing && withdrawBalancePreserved);
    }

    // allow receiving Ether when c sends to this contract
    receive() external payable {}
}

